/// C 端 MFA(TOTP)二步验证管理
class MfaServiceClient {
  final ClientTransport _transport;

  MfaServiceClient(this._transport);

  /// 凭密码授权签发的一次性挑战令牌 + TOTP 验证码换正式令牌(免鉴权,登录流程第二步)
  Future<AuthenticationServiceV1LoginResponse> verifyMFAChallenge(AuthenticationServiceV1VerifyMFAChallengeRequest request, {Map<String, String>? headers}) async {
    final path = '/app/v1/mfa/verify';
    final body = jsonEncode(request.toJson());
    final result = await _transport.unary(path, 'POST', body, TransportMeta(
      service: 'MfaService',
      method: 'VerifyMFAChallenge',
    ), headers: headers);
    return AuthenticationServiceV1LoginResponse.fromJson(result as Map<String, dynamic>);
  }

  /// 发起绑定(鉴权;生成 TOTP 密钥与 otpauth URI,须 Confirm 激活)
  Future<AuthenticationServiceV1MfaSetupStartResponse> mfaSetupStart(AuthenticationServiceV1MfaSetupStartRequest request, {Map<String, String>? headers}) async {
    final path = '/app/v1/mfa/setup:start';
    final body = jsonEncode(request.toJson());
    final result = await _transport.unary(path, 'POST', body, TransportMeta(
      service: 'MfaService',
      method: 'MfaSetupStart',
    ), headers: headers);
    return AuthenticationServiceV1MfaSetupStartResponse.fromJson(result as Map<String, dynamic>);
  }

  /// 确认绑定(鉴权;验证码通过后启用)
  Future<Map<String, dynamic>> mfaSetupConfirm(AuthenticationServiceV1MfaSetupConfirmRequest request, {Map<String, String>? headers}) async {
    final path = '/app/v1/mfa/setup:confirm';
    final body = jsonEncode(request.toJson());
    final result = await _transport.unary(path, 'POST', body, TransportMeta(
      service: 'MfaService',
      method: 'MfaSetupConfirm',
    ), headers: headers);
    return result as Map<String, dynamic>;
  }

  /// 解绑(鉴权;验证码通过后清除)
  Future<Map<String, dynamic>> mfaDisable(AuthenticationServiceV1MfaDisableRequest request, {Map<String, String>? headers}) async {
    final path = '/app/v1/mfa:disable';
    final body = jsonEncode(request.toJson());
    final result = await _transport.unary(path, 'POST', body, TransportMeta(
      service: 'MfaService',
      method: 'MfaDisable',
    ), headers: headers);
    return result as Map<String, dynamic>;
  }

  /// 生成/重生成备份码(鉴权;明文仅一次)
  Future<AuthenticationServiceV1MfaBackupCodesResponse> mfaBackupCodesRegenerate(AuthenticationServiceV1MfaBackupCodesRegenerateRequest request, {Map<String, String>? headers}) async {
    final path = '/app/v1/mfa/backup-codes:regenerate';
    final body = jsonEncode(request.toJson());
    final result = await _transport.unary(path, 'POST', body, TransportMeta(
      service: 'MfaService',
      method: 'MfaBackupCodesRegenerate',
    ), headers: headers);
    return AuthenticationServiceV1MfaBackupCodesResponse.fromJson(result as Map<String, dynamic>);
  }
}

