class ApiClient {
  final ClientTransport _transport;

  AuthenticationServiceClient? _authenticationService;
  MfaServiceClient? _mfaService;
  UserProfileServiceClient? _userProfileService;

  ApiClient(this._transport);

  AuthenticationServiceClient get authenticationService {
    _authenticationService ??= AuthenticationServiceClient(_transport);
    return _authenticationService!;
  }

  MfaServiceClient get mfaService {
    _mfaService ??= MfaServiceClient(_transport);
    return _mfaService!;
  }

  UserProfileServiceClient get userProfileService {
    _userProfileService ??= UserProfileServiceClient(_transport);
    return _userProfileService!;
  }

  /// Closes all service clients and releases resources.
  void dispose() {
    _authenticationService = null;
    _mfaService = null;
    _userProfileService = null;
  }
}

ApiClient createApiClient(ClientTransport transport) {
  return ApiClient(transport);
